      id: 'uses-webp-images',
      title: 'Serve images in next-gen formats',
      scoreDisplayMode: ByteEfficiencyAudit.SCORING_MODES.NUMERIC,
      description: 'Image formats like JPEG 2000, JPEG XR, and WebP often provide better ' +
